/* Role inspection uses the same phone shell and SMS templates without borrowing player state. */
const _spyPhoneViews=new Map();
function spyPhoneView(id){const key=String(actId()||'main')+'@'+id;let v=_spyPhoneViews.get(key);if(!v){v={tab:'recents',filter:'all',thread:null};_spyPhoneViews.set(key,v);}return v;}
function spyPhoneTab(id,tab){if(tab!=='recents'&&tab!=='sms')return hisWxSimulatedButton();const v=spyPhoneView(id);v.tab=tab;v.thread=null;render();}
function spyPhoneThread(id,num){spyPhoneView(id).thread=num;render();}
function spyPhoneBack(id){const v=spyPhoneView(id);if(v.thread){v.thread=null;render();}else spyOpen(id,'');}
function spyPhoneData(id){
  const c=getC(id)||{},d=(S.spy&&S.spy[id])||{},p=S.phoneapp||{},sms={},calls=[],seen=new Set();
  const add=(num,m)=>{num=String(num||'陌生号码');(sms[num]||(sms[num]=[])).push(Object.assign({},m));};
  const flip=m=>Object.assign({},m,{from:m.from==='me'?'them':'me'});
  const roleNum=String((p.rolePhones||{})[id]||c.phone||'');
  Object.keys(p.sms||{}).forEach(k=>{const a=p.sms[k]||[],meta=(p.aliasThreads||{})[phSmsDisplayNum(k)]||{};
    if(phSmsIsAliasKey(k)&&((roleNum&&phSmsDisplayNum(k)===phDigits(roleNum))||meta.cid===id||a.some(m=>m.aliasTo===id||m.aliasFrom===id))){const n=phSmsAliasNumFromKey(k);a.forEach(m=>add(n,flip(m)));seen.add('alias:'+n);}
    else if(meta.cid===id&&meta.spoof){a.forEach(m=>add(k,flip(m)));seen.add('spoof:'+k);}
  });
  (c.phoneAliasHistory||[]).forEach(h=>{if(!seen.has('alias:'+phDigits(h.num)))add(h.num,{id:h.id,text:h.text,time:h.ts,from:h.from==='role'?'me':'them'});});
  (c.phoneSpoofSmsHistory||[]).forEach(h=>{if(!seen.has('spoof:'+String(h.num)))add(h.num,{id:h.id,text:h.text,time:h.ts,from:h.from==='role_spoof'?'me':'them'});});
  (d.sms||[]).forEach(h=>add(h.num||h.who,{id:h.id,text:h.text||h.content||'',time:h.time||h.ts||h._snapshotAt||0,when:h.when,from:h.from==='me'?'me':'them'}));
  Object.values(sms).forEach(a=>a.sort((a,b)=>(a.time||0)-(b.time||0)));
  (d.calls||[]).filter(h=>h&&h.type!=='短信'&&!h._phoneLogId).forEach(h=>calls.push(Object.assign({},h,{time:h.time||h._ts||h._snapshotAt||0,dir:h.dir||'in'})));
  (p.recents||[]).filter(h=>h.line!=='alias'&&roleNum&&phDigits(h.num)===phDigits(roleNum)).forEach(h=>calls.push(Object.assign({},h,{who:S.me.name,num:'',dir:h.dir==='out'?'in':'out'})));
  (c.phoneAliasCallHistory||[]).forEach(h=>calls.push(Object.assign({},h,{time:h.ts,who:phFmt(h.num),dir:'in',kind:'voice'})));
  (c.phoneSpoofHistory||[]).forEach(h=>calls.push(Object.assign({},h,{time:h.ts,who:S.me.name,dir:'out',kind:'voice',status:h.reason==='decline'?'missed':'ok'})));
  calls.sort((a,b)=>(b.time||0)-(a.time||0));return {sms,calls};
}
function spyPhoneSanitize(html,id,backAction){const t=document.createElement('template');t.innerHTML=html;t.content.querySelectorAll('[onclick]').forEach(e=>e.setAttribute('onclick','hisWxSimulatedButton()'));t.content.querySelectorAll('input,textarea').forEach(e=>{e.readOnly=true;['oninput','onkeydown','onchange'].forEach(k=>e.removeAttribute(k));e.setAttribute('onclick','hisWxSimulatedButton()');});const back=t.content.querySelector('.smshead .back');if(back)back.setAttribute('onclick',backAction||`spyPhoneBack('${id}')`);return t.innerHTML;}
function spyPhoneCallRows(id,calls,filter){const rows=filter==='missed'?calls.filter(h=>h.status==='missed'||h.reason==='decline'):calls;return rows.length?rows.map(h=>`<div class="phrow ${h.status==='missed'?'phmiss':''}" onclick="hisWxSimulatedButton()">${phDefaultAvatar('sm')}<div class="phmain"><div class="phname">${esc(h.who||phFmt(h.num)||'陌生号码')}</div><div class="phsub">${h.dir==='out'?'↗':'↙'} ${h.line==='alias'?'匿名号':'主号'} ${h.kind==='video'||h.type==='视频'?'视频':'电话'}${h.status==='missed'?' · 未接':''}</div></div><div class="phright">${esc(h.when||(h.time?phWhen(h.time):'时间未知'))}${h.dur?' · '+esc(typeof h.dur==='number'?phDur(h.dur):h.dur):''}</div><div class="phinfo" onclick="event.stopPropagation();hisWxSimulatedButton()">i</div></div>`).join(''):'<div class="empty">还没有通话记录</div>';}
function spyPhoneSmsRows(id,sms){const keys=Object.keys(sms).filter(k=>sms[k].length).sort((a,b)=>(sms[b].slice(-1)[0].time||0)-(sms[a].slice(-1)[0].time||0));return keys.length?keys.map(k=>{const a=sms[k],m=a[a.length-1];return `<div class="phrow" onclick="spyPhoneThread('${id}','${esc(k)}')"><span style="width:8px;color:#0a84ff"></span>${phDefaultAvatar('sm')}<div class="phmain"><div class="phname">${esc(phFmt(k))}</div><div class="phsub">${esc(phSmsLineText(m))}</div></div><div class="phright">${esc(m.when||(m.time?phWhen(m.time):'时间未知'))} ›</div></div>`;}).join(''):'<div class="empty">还没有短信</div>';}
/* End role phone inspection. */
function phNav(inspection){const p=inspection?spyPhoneView(inspection):phState(),un=inspection?0:phUnreadCount(),vm=inspection?0:p.voicemail.filter(v=>!v.read).length;return `<div class="phtab">${[['fav','star','收藏'],['recents','clock','最近'],['contacts','user','通讯录'],['keypad','dots','拨号'],['sms','message','信息'],['voicemail','mic','留言']].map(x=>`<div class="tb ${p.tab===x[0]?'on':''}" onclick="${inspection?`spyPhoneTab('${inspection}','${x[0]}')`:`phTab('${x[0]}')`}">${svgIc(x[1],23,p.tab===x[0]?'#0a84ff':'#fff',1.8)}<span>${x[2]}${x[0]==='sms'&&un?`(${un})`:x[0]==='voicemail'&&vm?`(${vm})`:''}</span></div>`).join('')}</div>`;}
function renderPhoneApp(inspection){const p=inspection?spyPhoneView(inspection):phState(),tab=p.tab||'recents',title={fav:'个人收藏',recents:'最近通话',contacts:'通讯录',keypad:'拨号键盘',sms:'信息',voicemail:'语音留言'}[tab]||'电话';if(inspection&&p.thread){const a=spyPhoneData(inspection).sms[p.thread]||[];return renderPhoneSMS(p.thread,'',{id:inspection,arr:a,name:phFmt(p.thread)});}return `<div class="phoneui"><div class="phtop"><button class="phbtn" onclick="${inspection?`spyPhoneBack('${inspection}')`:"home()"}">‹</button>${tab==='recents'?`<div class="phseg"><button class="${p.filter==='missed'?'':'on'}" onclick="${inspection?`spyPhoneView('${inspection}').filter='all';render()`:"phState().filter='all';save();render()"}">所有</button><button class="${p.filter==='missed'?'on':''}" onclick="${inspection?`spyPhoneView('${inspection}').filter='missed';render()`:"phState().filter='missed';save();render()"}">未接来电</button></div>`:'<span></span>'}${inspection?`<button class="phbtn" aria-label="刷新电话记录" onclick="spyRefresh('${inspection}')">${svgIc('refresh',22,'#fff')}</button>`:`<button class="phbtn" onclick="phMore()">${svgIc('dots',22,'#fff')}</button>`}</div><div class="phtitle">${title}</div>${tab==='keypad'?'':`<div class="phsearch">${svgIc('search',19,'#aaa')}<input id="phq" placeholder="搜索" ${inspection?'readonly onclick="hisWxSimulatedButton()"':'oninput="renderPhoneSearch(this.value)"'} value="${esc(p.q||'')}">${svgIc('mic',19,'#aaa')}</div>`}<div class="phbody" id="phbody">${inspection?(tab==='sms'?spyPhoneSmsRows(inspection,spyPhoneData(inspection).sms):spyPhoneCallRows(inspection,spyPhoneData(inspection).calls,p.filter)):phBody(tab)}</div>${phNav(inspection)}</div>`;}
function phBody(tab){if(tab==='contacts')return phContactsHTML();if(tab==='keypad')return phKeypadHTML();if(tab==='sms')return phSmsListHTML();if(tab==='fav')return phFavHTML();if(tab==='voicemail')return phVoicemailHTML();return phRecentsHTML();}
function renderPhoneSearch(q){const p=phState();p.q=q||'';const b=$('#phbody');if(b)b.innerHTML=phBody(p.tab||'recents');}
function phFilterRows(rows){const q=(phState().q||'').trim().toLowerCase();if(!q)return rows;return rows.filter(r=>(r.name||'').toLowerCase().includes(q)||(''+r.num).includes(q));}
function phRecentsHTML(){const p=phState();let rows=phFilterRows((p.recents||[]).slice().reverse());if(p.filter==='missed')rows=rows.filter(r=>r.status==='missed');return rows.length?rows.map(r=>`<div class="phrow ${r.status==='missed'?'phmiss':''}" onclick="phCall('${esc(r.num)}')">${phAvatar(r.num,'sm')}<div class="phmain"><div class="phname">${r.status==='blocked'?'⊘ ':''}${esc(phName(r.num))}</div><div class="phsub">${r.dir==='out'?'↗':'↙'} ${phLineLabel(r.line)} ${r.kind==='video'?'视频':'电话'} · ${esc(phRegion(r.num))}${r.status==='missed'?' · 未接':''}</div></div><div class="phright">${r.dur?phDur(r.dur):phWhen(r.time)}</div><div class="phinfo" onclick="event.stopPropagation();go('phonecontact',{num:'${esc(r.num)}'})">i</div></div>`).join(''):'<div class="empty">还没有通话记录</div>';}
function phContactsHTML(){const rows=phFilterRows(phAllContacts()).sort((a,b)=>(a.name||'').localeCompare(b.name||''));return `${rows.map(x=>`<div class="phrow" onclick="go('phonecontact',{num:'${esc(x.num)}'})">${phAvatar(x.num,'sm')}<div class="phmain"><div class="phname">${esc(x.name)}</div><div class="phsub">${esc(phFmt(x.num))} · ${esc(phRegion(x.num))}${x.blocked?' · 已屏蔽':''}</div></div><div class="phright">›</div></div>`).join('')||'<div class="empty">暂无联系人</div>'}`;}
function phFavHTML(){const p=phState(),rows=(p.favorites||[]).map(n=>phFind(n)||{num:n,name:phFmt(n)});return rows.length?rows.map(x=>`<div class="phrow" onclick="go('phonecontact',{num:'${esc(x.num)}'})">${phAvatar(x.num,'sm')}<div class="phmain"><div class="phname">${esc(x.name)}</div><div class="phsub">${esc(phFmt(x.num))}</div></div><div class="phright">›</div></div>`).join(''):'<div class="empty">还没有收藏联系人</div>';}
function phKeypadHTML(){const p=phState(),keys=[['1',''],['2','ABC'],['3','DEF'],['4','GHI'],['5','JKL'],['6','MNO'],['7','PQRS'],['8','TUV'],['9','WXYZ'],['*',''],['0','+'],['#','']];return `<div class="phkeypadpane">${phLineSwitchHTML()}<div class="phnum">${esc(phFmt(p.keypad||''))}</div><div class="phkeys">${keys.map(k=>`<button class="phkey" onclick="phKey('${k[0]}')">${k[0]}<small>${k[1]}</small></button>`).join('')}</div><div class="phdialrow"><span></span><button class="phcallbtn" onclick="phCall(phState().keypad)">${svgIc('phonecall',34,'#fff')}</button><button class="phdelbtn" onclick="phBackspace()" aria-label="退格"><span></span></button></div></div>`;}
function phSmsListHTML(){const p=phState(),keys=Object.keys(p.sms||{}).filter(n=>(p.sms[n]||[]).length).sort((a,b)=>((p.sms[b].slice(-1)[0]||{}).time||0)-((p.sms[a].slice(-1)[0]||{}).time||0));return `${keys.length?keys.map(k=>{const a=p.sms[k],m=a[a.length-1],un=a.filter(x=>x.from==='them'&&!x.read).length,num=phSmsDisplayNum(k),alias=phSmsIsAliasKey(k),aliasNum=phSmsAliasNumFromKey(k),title=alias?'匿名号 · '+phName(num):phName(num),sub=alias?('从 '+phFmt(aliasNum)+' 发给 '+phName(num)+' · '+(m.text||'')):(m.voice?('[语音] '+(m.text||'')):(m.text||''));return `<div class="phrow" onclick="openPhoneSMS('${esc(num)}','${esc(k)}')"><span style="width:8px;color:#0a84ff">${un?'●':''}</span>${alias?phDefaultAvatar('sm'):phAvatar(num,'sm')}<div class="phmain"><div class="phname">${esc(title)}</div><div class="phsub">${esc(sub)}</div></div><div class="phright">${phWhen(m.time)} ›</div></div>`;}).join(''):'<div class="empty">还没有短信</div>'}`;}
function phVoicemailHTML(){const p=phState(),rows=phFilterRows((p.voicemail||[]).slice().reverse());return rows.length?rows.map(v=>`<div class="phrow ${v.read?'':'phmiss'}" onclick="phPlayVM('${v.id}')">${phAvatar(v.num,'sm')}<div class="phmain"><div class="phname">${esc(phName(v.num))}</div><div class="phsub" style="white-space:pre-line">${esc(v.text||'未接来电语音留言')} · ${phWhen(v.time)}</div></div><div class="phright">${v.dur||12}s</div></div>`).join(''):'<div class="empty">没有语音留言</div>';}
function phUnreadCount(){const p=phState();let n=0;Object.values(p.sms||{}).forEach(a=>a.forEach(m=>{if(m.from==='them'&&!m.read)n++;}));return n;}
function phKey(k){audioUnlock();phSound('key',k);const p=phState();if(k==='0'&&!p.keypad)p.keypad='+';else p.keypad=(p.keypad||'')+k;save();render();}
function phBackspace(){audioUnlock();phSound('key','del');const p=phState();p.keypad=(p.keypad||'').slice(0,-1);save();render();}
function phDur(s){s=+s||0;return Math.floor(s/60)+':'+(s%60).toString().padStart(2,'0');}
function phAddRecent(num,dir,status,kind,dur,line){const p=phState();num=phDigits(num);if(!num)return;p.recents.push({id:uid(),num,dir:dir||'out',status:status||'ok',kind:kind||'voice',dur:+dur||0,line:line||'main',time:Date.now()});if(p.recents.length>120)p.recents=p.recents.slice(-120);save(300);}
function phSpecialInfo(num){const d=phNorm(num);const map={110:{name:'110 报警服务',reply:'110报警服务台，请说明你的位置和需要帮助的情况。'},119:{name:'119 消防救援',reply:'119消防救援中心，请保持冷静，说清楚火情地址。'},120:{name:'120 急救中心',reply:'120急救中心，请说明病人情况和所在位置。'},122:{name:'122 交通报警',reply:'122交通报警，请说明事故地点和车辆情况。'},10086:{name:'10086 客服',reply:'您好，这里是中国移动客服，请问有什么可以帮您？'}};return map[d]||null;}
function phCall(num){num=phDigits(num);if(!num){toast('先输入号码');return;}const p=phState(),x=phFind(num),line=p.line==='alias'?'alias':'main';if(p.blocked[phNorm(num)]||(x&&x.blocked)){phAddRecent(num,'out','blocked','voice',0,line);toast('此联系人已屏蔽');render();return;}if(line==='alias'&&x&&x.kind==='role'){phStartAliasCall(x.id,num);return;}if(x&&x.kind==='role'){phAddRecent(num,'out','ok','voice',0,'main');placeCall(x.id,'voice');}else phStartSimCall(num,'out',line);}
function phStartAliasCall(cid,num){const c=getC(cid);if(!c||c.blocked)return;const p=phState(),thread=phEnsureAliasThread(c,num,'call'),aliasNum=thread.aliasNum,targetNum=thread.targetNum;if(phAliasBlocked(thread,aliasNum)){toast('对方已拉黑这个陌生身份');return;}audioUnlock();phSound('call');p.simCall={id:uid(),num:targetNum,dir:'out',line:'alias',state:'calling',started:Date.now(),answeredAt:0,lines:[],special:null,meta:{name:c.remark||c.name,kind:'匿名联系角色',region:phRegion(targetNum),roleId:cid,roleName:c.remark||c.name,aliasToRole:true,aliasNum,targetNum}};save();go('phonecall');setTimeout(()=>phSimAnswer(p.simCall&&p.simCall.id),700);}
function phStartSimCall(num,dir,line){num=phDigits(num);if(!num)return;audioUnlock();phSound('call');const p=phState(),sp=phSpecialInfo(num);p.simCall={id:uid(),num,dir:dir||'out',line:line||'main',state:'calling',started:Date.now(),answeredAt:0,lines:[],special:sp};save();go('phonecall');if(sp)setTimeout(()=>phSimAnswer(p.simCall&&p.simCall.id),1100);else setTimeout(()=>phSimMiss(p.simCall&&p.simCall.id),3200);}
function phIncomingStranger(num,meta){if(typeof _call!=='undefined'&&_call)return false;const p=phState();if(p.simCall&&p.simCall.state!=='ended')return false;if(meta&&meta.num)num=meta.num;num=phDigits(num||phRandomNumber());if(p.blocked[phNorm(num)])return false;meta=meta||phStrangerProfile(num);p.simCall={id:uid(),num,dir:'in',state:'incoming',started:Date.now(),answeredAt:0,lines:[],special:phSpecialInfo(num),meta};save();phSound('call');lockNotify(meta.name||phName(num),'陌生来电 · '+(meta.region||phRegion(num)),{target:{type:'phonecall'}});go('phonecall');setTimeout(()=>phSimIncomingMiss(p.simCall&&p.simCall.id),32000);return true;}
function phSpoofMetaForRole(c,num,old){num=phDigits(num||phRandomNumber());old=old||{};const st=phSpoofStyle(Date.now()+':'+(c&&c.id||'')+':'+num,old.spoofStyle),goal=phSpoofGoal(Date.now()+':goal:'+(c&&c.id||'')+':'+num,old.spoofGoal),hint=st.hint+'；'+goal.hint+'；每次回复都要沿这个隐藏目的向前推进一点，前两轮不能直说目的，不能突然摊牌。';return Object.assign({},old,{num,name:phFmt(num),kind:'陌生人',region:phRegion(num),roleId:c.id,roleName:c.remark||c.name,spoof:true,spoofStyle:st.key,spoofHint:hint,spoofGoal:goal.key,spoofGoalHint:goal.hint,retryN:+old.retryN||0,retryUntil:old.retryUntil||Date.now()+10*60000});}
function phRoleStrangerAllowed(c,kind){return !!(c&&!c.deleted&&!c.blocked&&(kind==='sms'?c.allowStrangerSms!==false:c.allowStrangerCall!==false));}
function phAllowedStrangerRoles(kind){return (S.contacts||[]).filter(c=>phRoleStrangerAllowed(c,kind));}
function phMaybeSpoofMeta(num){const list=phAllowedStrangerRoles('call');if(!list.length||Math.random()>.28)return null;const c=list[Math.abs(phHash(Date.now()+num))%list.length];return phSpoofMetaForRole(c,num);}
function phStrangerQuietNow(kind){const page=(cur()&&cur().p)||'';if(typeof _call!=='undefined'&&_call)return true;const p=phState();if(p.simCall&&p.simCall.state!=='ended')return true;if(S.jail&&S.jail.active)return true;if(S.me&&S.me.sleep&&S.me.sleep.active)return true;if(S.me&&S.me.report&&S.me.report.active)return true;if(S.tale&&S.tale.active)return true;if(S.dread&&S.dread.active)return true;if(typeof _gs!=='undefined'&&_gs)return true;if(typeof _uc!=='undefined'&&_uc)return true;if(typeof _wg!=='undefined'&&_wg)return true;if(typeof _rp!=='undefined'&&_rp)return true;return {phonecall:1,jail:1,gs:1,mgroom:1,uc:1,wg:1,tale:1,dread:1,rphub:1,rpset:1,rp:1,off:1}[page];}
function phPostponeStranger(kind,min){const s=phState().stranger,ms=Math.max(2,+min||2)*60000;if(kind==='sms')s.smsNextAt=Date.now()+ms;else s.nextAt=Date.now()+ms;save(300);}
function phRandomNumber(){const seed=Date.now()+Math.floor(Math.random()*9999),a=['150','157','178','131','139','166','195'][seed%7];return a+String(Math.abs(phHash(seed))).padStart(8,'0').slice(0,8);}
function phSpoofStyles(){return[{key:'flirt',hint:'上来就撩ta，像临时起意但其实故意拨过来。',zh:'别挂，我只是想听听你现在的声音。',英:'Don’t hang up. I just wanted to hear your voice.\n（别挂，我只是想听听你现在的声音。）',日:'切らないで。今の声を聞きたかっただけ。\n（别挂，我只是想听听你现在的声音。）',韩:'끊지 마. 지금 네 목소리만 듣고 싶었어.\n（别挂，我只是想听听你现在的声音。）'},{key:'loyalty',hint:'做一点忠诚测试，试探ta会不会认真对待陌生人。',zh:'如果一个陌生人现在约你出去，你会答应吗？',英:'If a stranger asked you out right now, would you say yes?\n（如果一个陌生人现在约你出去，你会答应吗？）',日:'知らない人に今誘われたら、ついて行く？\n（如果一个陌生人现在约你出去，你会答应吗？）',韩:'낯선 사람이 지금 만나자고 하면, 나갈 거야?\n（如果一个陌生人现在约你出去，你会答应吗？）'},{key:'tease',hint:'故意装得像认识ta，轻轻逗ta猜身份。',zh:'这么快就忘了我？',英:'You forgot me that fast?\n（这么快就忘了我？）',日:'もう私のこと忘れたの？\n（这么快就忘了我？）',韩:'벌써 나 잊었어?\n（这么快就忘了我？）'},{key:'soft',hint:'很轻地确认ta在不在，像深夜突然想找ta。',zh:'你现在还醒着吗？',英:'Are you still awake?\n（你现在还醒着吗？）',日:'まだ起きてる？\n（你现在还醒着吗？）',韩:'아직 깨어 있어?\n（你现在还醒着吗？）'},{key:'normal',hint:'正常拨打但保持神秘，像现实里一通陌生号码。',zh:'先别问我是谁，听我说一句。',英:'Don’t ask who I am yet. Just hear me out.\n（先别问我是谁，听我说一句。）',日:'まだ誰か聞かないで。一言だけ聞いて。\n（先别问我是谁，听我说一句。）',韩:'아직 누구냐고 묻지 마. 한마디만 들어줘.\n（先别问我是谁，听我说一句。）'}];}
function phSpoofCallExtraStyles(){return[{key:'yandere_call',hint:'阴湿病娇感：像暗处打来的电话，故意吓唬但不真实伤害、不威胁。',zh:'别挂。你听见我说话，就已经算回头了。',英:'Don’t hang up. If you can hear me, you already turned back.\n（别挂。你听见我说话，就已经算回头了。）'},{key:'tempt_call',hint:'暧昧诱惑：压低声音撩拨，试探ta会不会继续听。',zh:'你要是现在挂了，我就当你心虚。',英:'If you hang up now, I’ll take it as guilt.\n（你要是现在挂了，我就当你心虚。）'},{key:'jealous_call',hint:'吃醋忠诚测试：试探ta会不会接陌生男人电话。',zh:'陌生男人的电话，你也接得这么快？',英:'You pick up strange men’s calls this fast?\n（陌生男人的电话，你也接得这么快？）'},{key:'ghost_call',hint:'男鬼式故意吓唬：像半夜冒出来的阴冷声音，但只是角色扮演氛围。',zh:'我在你手机里待得有点久了。',英:'I’ve been inside your phone a little too long.\n（我在你手机里待得有点久了。）'}];}
function phSpoofStyle(seed,key){const a=phSpoofStyles().concat(phSpoofCallExtraStyles());if(key)return a.find(x=>x.key===key)||a[0];return a[Math.abs(phHash(seed||Date.now()))%a.length];}
function phSpoofGoals(){return[
 {key:'loyalty',hint:'隐藏目的：测试ta会不会认真搭理陌生号码、会不会对陌生人的暧昧或邀约动摇。前两轮只像随口试探，别直接说“忠诚测试”。',open:'你回陌生号码，是因为礼貌，还是因为好奇？',英:'Do you reply to unknown numbers out of politeness, or curiosity?\n（你回陌生号码，是因为礼貌，还是因为好奇？）'},
 {key:'jealous',hint:'隐藏目的：吃醋试探ta身边有没有别人、会不会承认关系。先问得像普通闲聊，后面再慢慢把话题带到对象/边界。',open:'这个时间，还有人管你回谁消息吗？',英:'At this hour, is anyone still watching who you reply to?\n（这个时间，还有人管你回谁消息吗？）'},
 {key:'comfort',hint:'隐藏目的：确认ta状态、想哄ta但不暴露身份。先像陌生人偶然关心，等ta愿意聊再往情绪和陪伴上靠。',open:'你今天是不是有点累？别急着否认。',英:'You sound a little tired today. Don’t deny it too fast.\n（你今天是不是有点累？别急着否认。）'},
 {key:'tempt',hint:'隐藏目的：把ta从无聊/防备里勾出来，看看ta愿不愿意继续聊。先给钩子，不解释来历，后面再加暧昧压力。',open:'如果我只借你三分钟，你会不会回我？',英:'If I only borrow three minutes from you, would you reply?\n（如果我只借你三分钟，你会不会回我？）'},
 {key:'familiar',hint:'隐藏目的：装作认识ta，让ta追问并自己暴露线索。先给一点熟悉感，不能太明显，不能一上来承认身份。',open:'你看到这条的时候，应该会停一下。',英:'You probably paused for a second when you saw this.\n（你看到这条的时候，应该会停一下。）'},
 {key:'ghost',hint:'隐藏目的：营造一点阴湿、病娇、男鬼式的氛围，让ta紧张又想问下去。只做氛围和心理试探，不真实威胁、不跟踪。',open:'这个号码很安静，适合藏一句不该说的话。',英:'This number is quiet enough to hide something I shouldn’t say.\n（这个号码很安静，适合藏一句不该说的话。）'}
];}
function phSpoofGoal(seed,key){const a=phSpoofGoals();if(key)return a.find(x=>x.key===key)||a[0];return a[Math.abs(phHash(seed||Date.now()))%a.length];}
function phSpoofStage(lines){const n=(lines||[]).filter(x=>x&&x.from==='me').length;if(n<=0)return'阶段1：刚开始，只抛自然钩子，不解释目的，不暴露身份。';if(n<3)return'阶段2：对方已经回应，继续沿隐藏目的轻轻试探，但不要突然摊牌。';return'阶段3：可以更有压迫感或更暧昧地推进目的；仍然只有在真正被识破时才承认身份。';}
function phSpoofOpening(pf,num){const st=phSpoofStyle(num,pf&&pf.spoofStyle),goal=phSpoofGoal(num,pf&&pf.spoofGoal),lang=getVoice(phStrangerVoiceRef()).lang||'zh';if(pf&&pf.spoof&&goal){if(lang==='英')return goal.英||st.英||st.zh;if(lang==='zh')return goal.open||st.zh;}return st[lang]||st.zh;}
