/* ===== 带效果发送（长按发送键） ===== */
let _phFxHold=0;
function phFxHoldStart(num,sk){clearTimeout(_phFxHold);_phFxHold=setTimeout(()=>{_phFxHold=0;phFxSendHold(num,sk);},420);}
function phFxHoldStop(){if(_phFxHold){clearTimeout(_phFxHold);_phFxHold=0;}}
